def transform(grid):
    # Create a copy of the grid to modify
    new_grid = [row[:] for row in grid]
    rows = len(grid)
    cols = len(grid[0])

    for r in range(rows):
        for c in range(cols):
            if grid[r][c] == 9:
                # Check for foreground pixels (non-9) in both left and right directions
                # by skipping consecutive 9s (background gaps)

                # Scan left
                l = c - 1
                while l >= 0 and grid[r][l] == 9:
                    l -= 1

                # Scan right
                r_idx = c + 1
                while r_idx < cols and grid[r][r_idx] == 9:
                    r_idx += 1

                # If valid foreground pixels are found on both sides
                if (l >= 0 and grid[r][l] != 9) and (r_idx < cols and grid[r][r_idx] != 9):
                    new_grid[r][c] = 4

    return new_grid
